-- Release 0002: subject integrity.
--
-- Generated by dryv/tools/subject-integrity.ts from the SubjectTable enum and the carrier tables of the snapshot; do not edit by hand.
-- Carriers (hold subject_table + subject_id): filesystem.media, legal.effects, source.relationships, source.verifications.
-- Policy: a subject row that is still referenced cannot be hard-deleted (RESTRICT). Soft deletion is unaffected.
create or replace function public.subject_exists(p_table text, p_id uuid) returns boolean
language plpgsql stable as $$
declare found boolean;
begin
  if p_table is null or p_id is null or p_table not in ('civic.bids', 'civic.contracts', 'civic.deliveries', 'civic.procurements', 'civic.project_features', 'civic.projects', 'civic.services', 'filesystem.file_extensions', 'filesystem.file_versions', 'filesystem.files', 'filesystem.folders', 'filesystem.media', 'filesystem.taggings', 'filesystem.tags', 'finance.appropriations', 'finance.budget_versions', 'finance.budgets', 'finance.debts', 'finance.fiscal_periods', 'finance.flows', 'finance.funds', 'geography.assets', 'geography.changes', 'geography.classifications', 'geography.features', 'geography.geometries', 'geography.identifiers', 'geography.names', 'geography.relationships', 'governance.authority_scopes', 'governance.holders', 'governance.institutions', 'governance.mandates', 'governance.offices', 'governance.relationships', 'legal.editions', 'legal.effects', 'legal.instruments', 'legal.names', 'legal.provisions', 'legal.references', 'legal.relationships', 'legal.translations', 'legal.wordings', 'official.branding', 'official.contacts', 'official.entities', 'official.identifiers', 'official.individuals', 'official.names', 'official.relationships', 'politics.alignments', 'politics.candidates', 'politics.coalitions', 'politics.contests', 'politics.elections', 'politics.electorates', 'politics.manifesto_items', 'politics.manifestos', 'politics.memberships', 'politics.option_results', 'politics.parties', 'politics.referendum_options', 'politics.results', 'reference.countries', 'reference.language_names', 'reference.languages', 'reference.patterns', 'reference.schemes', 'reference.topics', 'reference.units', 'reference.value_labels', 'reference.value_relations', 'reference.values', 'source.addresses', 'source.artifacts', 'source.attributions', 'source.captures', 'source.citations', 'source.discoveries', 'source.domains', 'source.editions', 'source.products', 'source.publishers', 'source.relationships', 'source.sources', 'source.verifications') then
    return false;
  end if;
  execute format('select exists (select 1 from %s where id = $1)', p_table::regclass) into found using p_id;
  return found;
end $$;

create or replace function public.assert_subject() returns trigger
language plpgsql as $$
begin
  if new.subject_table is not null and not public.subject_exists(new.subject_table, new.subject_id) then
    raise exception 'subject % % does not exist', new.subject_table, new.subject_id using errcode = 'foreign_key_violation';
  end if;
  return new;
end $$;

create or replace function public.guard_subject_delete() returns trigger
language plpgsql as $$
declare qualified text := tg_table_schema || '.' || tg_table_name;
begin
  if exists (select 1 from filesystem.media where subject_table = qualified and subject_id = old.id) then
    raise exception '% % is still referenced as a subject by filesystem.media', qualified, old.id using errcode = 'foreign_key_violation';
  end if;
  if exists (select 1 from legal.effects where subject_table = qualified and subject_id = old.id) then
    raise exception '% % is still referenced as a subject by legal.effects', qualified, old.id using errcode = 'foreign_key_violation';
  end if;
  if exists (select 1 from source.relationships where subject_table = qualified and subject_id = old.id) then
    raise exception '% % is still referenced as a subject by source.relationships', qualified, old.id using errcode = 'foreign_key_violation';
  end if;
  if exists (select 1 from source.verifications where subject_table = qualified and subject_id = old.id) then
    raise exception '% % is still referenced as a subject by source.verifications', qualified, old.id using errcode = 'foreign_key_violation';
  end if;
  return old;
end $$;

